# 1. reusable validated field using __set_name__
class Positive:
    def __set_name__(self, owner, name):
        self.public = name
        self.private = "_" + name
    def __get__(self, obj, objtype=None):
        if obj is None:
            return self                      # class access returns descriptor
        return getattr(obj, self.private)
    def __set__(self, obj, value):
        if value <= 0:
            raise ValueError(f"{self.public} must be positive")
        setattr(obj, self.private, value)

class Item:
    qty = Positive()
    price = Positive()
    def __init__(self, qty, price):
        self.qty, self.price = qty, price

print(Item(2, 10).qty)
```

