# 2. property with validation and a computed attribute
class Order:
    def __init__(self, subtotal):
        self._subtotal = subtotal
    @property
    def total(self):                         # read-only computed
        return round(self._subtotal * 1.18, 2)
    @property
    def subtotal(self):
        return self._subtotal
    @subtotal.setter
    def subtotal(self, v):
        if v < 0:
            raise ValueError("negative")
        self._subtotal = v

o = Order(100)
o.subtotal = 200
print(o.total)
