# 3. cached_property (non-data descriptor) and bound methods
from functools import cached_property
class Report:
    @cached_property
    def rows(self):
        print("computing")
        return [1, 2, 3]
r = Report()
r.rows; r.rows                               # prints once
print("rows" in r.__dict__, Report.__dict__["rows"].__class__.__name__)
